<!doctype html><html lang="en"><head><meta charset="utf-8"><title><?=e($inv['number'])?></title><style>body{font:12px DejaVu Sans,Arial,sans-serif;color:#202b32;margin:28px}h1{font-size:27px;margin:0;color:#df4c12}h2{font-size:17px}p{line-height:1.5}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{padding:9px 7px;border-bottom:1px solid #ddd;text-align:left}th{background:#f0f2f3}.right{text-align:right}.muted{color:#61707a}.totals{margin-left:45%;width:55%}.foot{margin-top:30px;font-size:10px;border-top:1px solid #ddd;padding-top:12px}tr{page-break-inside:avoid}@media print{.no-print{display:none}}</style></head><body>
