<?php if($receipt):?><p>Confirmed payment: <b><?=money($receipt['amount'],$o['currency'])?></b><br>Method: <?=e($receipt['method'])?> · Reference: <?=e($receipt['reference'])?><br>Confirmed: <?=e($receipt['verified_at'])?></p><?php else:?><p class="muted">An invoice is not proof of payment. Only confirmed payments listed below are receipts of funds.</p><?php endif?>
<table><thead><tr><th>Item / SKU</th><th>Qty</th><th class="right">Unit price</th><th class="right">Discount</th><th class="right">Tax</th><th class="right">Total</th></tr></thead><tbody><?php foreach($snap['items'] as $i):?><tr><td><?=e($i['name'])?><br><small><?=e($i['variant_label'])?> · <?=e($i['sku'])?></small></td><td><?=e($i['quantity'])?></td><td class="right"><?=money($i['unit_price'],'')?></td><td class="right"><?=money($i['discount'],'')?></td><td class="right"><?=money($i['tax'],'')?></td><td class="right"><?=money($i['total'],'')?></td></tr><?php endforeach?></tbody></table>
<table class="totals"><?php foreach(['Merchandise'=>$o['subtotal'],'Discount'=>$o['discount'],'Tax'=>$o['tax'],'Delivery'=>$o['shipping'],'Grand total'=>$o['total'],'Required at checkout'=>$o['due_now'],'Confirmed payments'=>$ledger['paid'],'Recorded refunds'=>$ledger['refunded'],'Outstanding balance'=>$ledger['outstanding']] as $k=>$v):?><tr><td><?=e($k)?></td><td class="right"><b><?=money($v,$o['currency'])?></b></td></tr><?php endforeach?></table>
<h2>Confirmed payment history</h2><table><tr><th>Date</th><th>Method / reference</th><th class="right">Amount</th></tr><?php foreach($payments as $p):?><tr><td><?=e($p['verified_at'])?></td><td><?=e($p['method'].' / '.$p['reference'])?></td><td class="right"><?=money($p['amount'],$o['currency'])?></td></tr><?php endforeach?><?php if(!$payments):?><tr><td colspan="3">No confirmed payments.</td></tr><?php endif?></table><p><?=nl2br(e($store['invoice_note']))?></p><p class="foot">Software Development by <a href="https://www.energeticedge.lk/" target="_blank" rel="noopener noreferrer">Energetic Edge (Pvt) Ltd</a></p></body></html>
